import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"49、【革】 離下兌上","description":"周易集註 - 49、【革】 離下兌上","frontmatter":{"title":"49、【革】 離下兌上","description":"周易集註 - 49、【革】 離下兌上"},"headers":[],"relativePath":"classics/jizhu/053.md","filePath":"classics/jizhu/053.md"}'),t={name:"classics/jizhu/053.md"};function h(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_49、【革】-離下兌上" tabindex="-1">49、【革】 離下兌上 <a class="header-anchor" href="#_49、【革】-離下兌上" aria-label="Permalink to “49、【革】 離下兌上”">​</a></h1><p>革者變革也，澤在上，火在下，火燃則水涸，水決則火滅。又中少二女不相得，故其卦為變革也。《序卦》：井道不可不革，故受之以革，所以次井。</p><p>己者信也，五性，仁義禮智信，惟信屬土，故以己言之，不言戊而言己者，離兌皆陰卦，故以陰土言。且文王圓圖，離兌中間乃坤土，故言己也。凡離火燒兌金斷裂者，惟土可接續，故月令於金火之間，置一中央土。十干丙丁戊己而後庚辛，言離火燒金，必有土方可孚契之意，日者離為日也。己日乃孚者，信我後革也。言當人心信我之時，相孚契矣，然後可革也。不輕於革之意，元亨利貞悔亡者，言除弊去害，掃而更之，大亨之道也。然必利於正，亨於正，則革之，當其可而悔亡矣。蓋不信而革，必生其悔，惟亨而正，則人心信我矣，所以己日乃孚，而後革也。</p><p>《彖》曰：革，水火相息，二女同居，其志不相得，曰革。己日乃孚，革而信之，文明以說，大亨以正，革而當，其悔乃亡。天地革而四時成，湯武革命，順乎天而應乎人。革之時大矣哉!</p><p>以卦象釋卦名，以卦德釋卦辭，而極贊之。火燃則水乾，水決則火滅，又相滅息之勢。少女志在艮，中女志在坎，有不相得之情。水火以滅息為革，二女以不能同居，各出嫁為革，故曰革。革而信之者，言革而人相信也。東征西怨，南征北怨，革而信之之事也。離之德明，兌之德悅，明則識事理而所革不茍。悅則順時勢而所革不驟。大亨者，除弊興利，一事之大亨也。伐暴救民，舉世之大亨也。以正者，揆之天理而順，質之人心而安也。又亨又正，則革之攸當，所以悔亡，正所謂革而信之也。陽極則陰生而革乎陽，陰極則陽生而革乎陰，故陰往陽來而為春夏，陽往陰來而為秋冬，四時成矣。命者，王者易姓受命也。王者之興，受命於天，故曰革命。天命當誅，順天也，人心共忿，應人也。天道改變，世道遷移，此革之大者，然要之同一時也。時不可革，天地聖人，不能先時;時所當革，天地聖人不能後時。革之時不其大哉，故曰：禮時為大，順次之，體次之，宜次之，稱次之。堯授舜，舜授禹，湯放桀，武王伐紂，時也。</p><h3 id="《象》曰-澤中有火-革-君子以治歷明時。" tabindex="-1">《象》曰：澤中有火，革，君子以治歷明時。 <a class="header-anchor" href="#《象》曰-澤中有火-革-君子以治歷明時。" aria-label="Permalink to “《象》曰：澤中有火，革，君子以治歷明時。”">​</a></h3><p>水中有火，水若盛則息火，火或盛則息水，此相革之象也。歷者經歷也，次也數也，行也過也，蓋日月五緯之躔次也。又作歷時者，四時也。治歷以明其時，晝夜者一日之革也，晦朔者一月之革也，分至者一年之革也，元會運世者萬古之革也。</p><p>初九，鞏用黃牛之革。</p><p>離為牛，牛之象也。中爻幹錯坤，黃之象也。鞏者固也，以皮束物也。束之以黃牛之革，則固之至矣。此爻變，即遁之艮止矣。艮止故不革，所以爻辭同。本卦以離火革兌金，下三爻主革者也，故二三言革，上三爻受革者也，故四言改，五六言變。</p><p>初九，當革之時，以陽剛之才，可以革矣。然居初位，卑無可革之權。上無應與，無共革之人，其不可有為也必矣。但陽性上行，火性上炎，恐其不能固守其不革之志。故聖人教佔者曰，革道匪輕，不可妄動，必固之以黃牛之革而後可，所以其象如此。</p><h3 id="《象》曰-鞏用黃牛-不可以有為也。" tabindex="-1">《象》曰：鞏用黃牛，不可以有為也。 <a class="header-anchor" href="#《象》曰-鞏用黃牛-不可以有為也。" aria-label="Permalink to “《象》曰：鞏用黃牛，不可以有為也。”">​</a></h3><p>無位無應之故。</p><p>六二，己日乃革之，徵吉無咎。</p><p>離為日，日之象也。陰土，己之象也。此爻變夬，情悅性健，故易於革。</p><p>六二以文明之才，而柔順中正，又上應九五之君，故人皆尊而信之，正所謂己日乃孚，革而信之者也，故有此象。佔者以此象而往，則人皆樂於耳目之新，有更化善治之吉，而無輕變妄動之咎矣，故佔者吉而無咎。</p><h3 id="《象》曰-己日革之-行有嘉也。" tabindex="-1">《象》曰：己日革之，行有嘉也。 <a class="header-anchor" href="#《象》曰-己日革之-行有嘉也。" aria-label="Permalink to “《象》曰：己日革之，行有嘉也。”">​</a></h3><p>應九五故有嘉，即徵吉二字也。</p><p>九三，徵兇貞厲，革言三就，有孚。</p><p>革言者，革之議論也。正應兌為口，言之象也。中爻幹為言，亦言之象也。就者成也，三就者，商度其革之利害可否，至再至三，而革之議論定也。離居三，三就之象也，故同人曰三歲不興，未濟曰三年有賞於大國，既濟曰三年克之，明夷曰三日不食，皆以離居其三也。若坎之三歲不得，困之三歲不覿，解之田獲三品，皆離之錯也。漸之三歲不孕，巽之田獲三品，皆以中爻合離也。豐之三歲不覿，以上六變而為離也。周公爻辭，其精至此。</p><p>九三以剛居剛，又居離之極，蓋革之躁動，而不能詳審者也。佔者以是往，兇可知矣。故雖事在所當革，亦有危厲。然當革之時，不容不革，故必詳審其利害可否，至於三就，則人信相孚，可以革矣。故教佔者必如此。</p><h3 id="《象》曰-革言三就-又何之矣" tabindex="-1">《象》曰：革言三就，又何之矣! <a class="header-anchor" href="#《象》曰-革言三就-又何之矣" aria-label="Permalink to “《象》曰：革言三就，又何之矣!”">​</a></h3><p>言議革之言，至於三就，則利害詳悉，可否分明，又復何之。</p><p>九四，悔亡有孚，改命吉。</p><p>改命者，到此已革矣。離交於兌，改夏之命令於秋矣。所以不言革而言改命，如湯改夏之命而為商，武改商之命而為周是也。九四之位，則改命之大臣，如伊尹太公是也。有孚者，上有孚於五，下而孚於民也。</p><p>九四卦己過中，己改其命矣。改命所繫匪輕，恐有所悔。然時當改命，不容不改者也，有何悔焉，是以悔亡。惟於未改之先，所改之志，孚於上下，則自獲其吉矣。故教佔者如此。</p><h3 id="《象》曰-改命之吉-信志也。" tabindex="-1">《象》曰：改命之吉，信志也。 <a class="header-anchor" href="#《象》曰-改命之吉-信志也。" aria-label="Permalink to “《象》曰：改命之吉，信志也。”">​</a></h3><p>志者，九四之志也。信志者，信九四所改之志也。上而信於君，下而信於民，必如是信，我方可改命也。信乃誠信，及爻辭孚字。</p><p>九五，大人虎變，未佔有孚。</p><p>陽剛之才，中正之德，居尊位而為革之主，得稱大人。兌錯艮，艮為虎，虎之象也。兌為正西，乃仲秋鳥獸毛毨，變之象也。幹之五則曰龍，革之五則曰虎，若以理論，揖遜者見其德，故稱龍。徵誅者見其威，故稱虎。三四之有孚者，乃水火相交之際，教佔者之有孚也。五之有孚，即湯武未革命之先，四海徯後之思，未佔而知其有孚矣。</p><p>九五以陽剛中正之才德，當兌金肅殺之秋，而為順天應人之舉。九四為改命之佐，己改其命矣，是以為大人者，登九五之位，而宇宙為之一新，故有大人虎變之象。此則不待佔決而自孚信者也。佔者有是德，方應是佔矣。</p><h3 id="《象》曰-大人虎變-其文炳也。" tabindex="-1">《象》曰：大人虎變，其文炳也。 <a class="header-anchor" href="#《象》曰-大人虎變-其文炳也。" aria-label="Permalink to “《象》曰：大人虎變，其文炳也。”">​</a></h3><p>文炳以人事論，改正朔，易服色，殊徽號，變犧牲，制禮作樂，炳乎其有文章是也。</p><p>上六，君子豹變，小人革面，徵兇，居貞吉。</p><p>楊子曰，狸變則豹，豹變則虎，故上六即以豹言之。革命之時，如鼓刀之叟，佐周受命，此豹變者也。又如蕭何諸臣，或為吏胥，或販繒屠狗，後皆開國承家，列爵分土，亦豹變者也。即班孟堅所謂雲起龍驤，化為侯王是矣。蓋九五既虎變而為天子，則上六即豹變而為公侯，若下句小人則百姓矣。革面者，言舊日面從於君者亦革也，如民之從桀紂者，不過面從而心實不從也。及湯師之興，則東征西怨，南征北怨，面從之偽皆革而心真實以向湯武矣。如民之從紂者，不過面從，而心實不從也。及化行南國，《泰誓》、《牧誓》則面從之偽皆格而心真實以向文武矣。蓋以力服人者，面從者也，以德服人者，中心悅而誠服也。心從者也，徵兇者。聖人作而萬物睹，別有所往，則為梗化之民而兇矣。居者徵之反也，君子豹變者，變其舊日之冠裳也。小人革面者，革其舊日之詐偽也。</p><p>上六當世道革成之後，而天命維新矣。公侯則開國承家，百姓則心悅誠服，有君子豹變，小人革面之象。故戒佔者，不守其改革之命，而別有所往則兇。能守其改革之命，則正而吉也。</p><h3 id="《象》曰-君子豹變-其文蔚也。小人革面-順以從君也。" tabindex="-1">《象》曰：君子豹變，其文蔚也。小人革面，順以從君也。 <a class="header-anchor" href="#《象》曰-君子豹變-其文蔚也。小人革面-順以從君也。" aria-label="Permalink to “《象》曰：君子豹變，其文蔚也。小人革面，順以從君也。”">​</a></h3><p>其文蔚者，冠裳一變，人物一新也。順以從君者，兌為悅，悅則順，即中心悅而誠服也。蔚本益母草，其花對節相開，亦如公侯相對而並列，故以蔚言之。豹次於虎，獸不同也。炳從虎，蔚從草，文之大小顯著不同也。</p>',37)])])}const f=e(t,[["render",h]]);export{_ as __pageData,f as default};
